 const b=res[0],dl=(v,v0)=>Number.isFinite(v)&&Number.isFinite(v0)?`${v-v0>=0?'+':''}${f(v-v0,1)} (${v-v0>=0?'+':''}${f(100*(v-v0)/v0,1)} %)`:'–';
